-- 10 Nov 2026: manufacturer-specific batch, five canonical identities.
-- Atomic private-only research intake, no live page, stock, model/alias writes.
DO $$
DECLARE n integer; inserted integer; old_pub integer; new_pub integer;
BEGIN
 SELECT count(*) INTO old_pub FROM public.motorcycle_universal_published_sections_v1;
 WITH expected(id,make,model) AS (VALUES (206,'KTM','1390 Super Duke R'),
(210,'KTM','990 Duke'),
(926,'KTM','125 Duke'),
(225,'Royal Enfield','Continental GT 535'),
(929,'Moto Guzzi','V7'))
 SELECT count(*) INTO n FROM expected e JOIN public.motorcycle_catalog_models m
 ON m.id=e.id AND m.manufacturer=e.make AND m.model=e.model
 WHERE NOT EXISTS(SELECT 1 FROM public.motorcycle_universal_page_sections_v1 s WHERE s.entity_type='model' AND s.model_id=e.id)
 AND NOT EXISTS(SELECT 1 FROM public.motorcycle_catalog_model_aliases a WHERE a.alias_model_id=e.id AND a.review_status<>'approved')
 AND EXISTS(SELECT 1 FROM public.motorcycle_catalog_manufacturers r WHERE r.display_name=e.make);
 IF n<>5 THEN RAISE EXCEPTION 'Blocked unsafe model identities (% of five)',n; END IF;
 INSERT INTO public.motorcycle_universal_page_sections_v1
 (entity_type,manufacturer_id,model_id,section_number,section_title,content,editorial_status,source_reference,published_at)
 SELECT 'model',NULL,v.model_id,v.slot,v.title,v.content,'draft','exact_model_factory_document:'||v.source_url,NULL
 FROM (VALUES (206,1,'Model introduction','{"summary":"The KTM 1390 Super Duke R is KTM''s large-capacity performance naked motorcycle, developed from the preceding Super Duke R family.","source_name":"KTM official model history","source_url":"https://press.ktm.com/news-introducing-the-ktm-1390-super-duke-r-the-beast-reborn?id=189969&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original model- and year-scoped evidence summary. Independent factual review and licensing required; do not publish automatically."}'::jsonb,'https://press.ktm.com/news-introducing-the-ktm-1390-super-duke-r-the-beast-reborn?id=189969&l=uk&menueid=5904'),
(206,7,'Documented model history','{"summary":"KTM''s UK release dated 28 November 2023 introduced the 2024 1390 Super Duke R and separately equipped EVO variant, with UK availability announced from January 2024.","source_name":"KTM official model history","source_url":"https://press.ktm.com/news-introducing-the-ktm-1390-super-duke-r-the-beast-reborn?id=189969&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original model- and year-scoped evidence summary. Independent factual review and licensing required; do not publish automatically."}'::jsonb,'https://press.ktm.com/news-introducing-the-ktm-1390-super-duke-r-the-beast-reborn?id=189969&l=uk&menueid=5904'),
(206,12,'2024-generation engineering','{"summary":"KTM documented a 1,350 cc LC8 engine rated at 190 horsepower and 145 Nm in its original 2024 launch information; this is not an all-year, all-market technical specification.","source_name":"KTM official model history","source_url":"https://press.ktm.com/news-introducing-the-ktm-1390-super-duke-r-the-beast-reborn?id=189969&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original model- and year-scoped evidence summary. Independent factual review and licensing required; do not publish automatically."}'::jsonb,'https://press.ktm.com/news-introducing-the-ktm-1390-super-duke-r-the-beast-reborn?id=189969&l=uk&menueid=5904'),
(210,1,'Model introduction','{"summary":"The KTM 990 Duke is a parallel-twin naked road motorcycle positioned between KTM''s middleweight and flagship large-capacity Duke models.","source_name":"KTM official model history","source_url":"https://press.ktm.com/news-the-2024-ktm-990-duke-hits-the-bullseye-with-sniper-like-accuracy?id=188614&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original model- and year-scoped evidence summary. Independent factual review and licensing required; do not publish automatically."}'::jsonb,'https://press.ktm.com/news-the-2024-ktm-990-duke-hits-the-bullseye-with-sniper-like-accuracy?id=188614&l=uk&menueid=5904'),
(210,7,'Documented model history','{"summary":"KTM announced the redesigned 990 Duke for the 2024 model year on 7 November 2023, with UK dealerships expected to receive it from February 2024.","source_name":"KTM official model history","source_url":"https://press.ktm.com/news-the-2024-ktm-990-duke-hits-the-bullseye-with-sniper-like-accuracy?id=188614&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original model- and year-scoped evidence summary. Independent factual review and licensing required; do not publish automatically."}'::jsonb,'https://press.ktm.com/news-the-2024-ktm-990-duke-hits-the-bullseye-with-sniper-like-accuracy?id=188614&l=uk&menueid=5904'),
(210,12,'Original 2024 model equipment','{"summary":"KTM''s launch article highlights a new chassis and swingarm, a five-inch bonded-glass display and USB-C charging; an optional Track mode must not be described as standard.","source_name":"KTM official model history","source_url":"https://press.ktm.com/news-the-2024-ktm-990-duke-hits-the-bullseye-with-sniper-like-accuracy?id=188614&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original model- and year-scoped evidence summary. Independent factual review and licensing required; do not publish automatically."}'::jsonb,'https://press.ktm.com/news-the-2024-ktm-990-duke-hits-the-bullseye-with-sniper-like-accuracy?id=188614&l=uk&menueid=5904'),
(926,1,'Model introduction','{"summary":"The KTM 125 Duke is the smallest-capacity roadster in the modern single-cylinder Duke family.","source_name":"KTM official model history","source_url":"https://press.ktm.com/news-ktms-no-bullshit-campaign-roars-to-life-with-the-brand-new-2024-single-cylinder-ktm-duke-line-up?id=184141&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original model- and year-scoped evidence summary. Independent factual review and licensing required; do not publish automatically."}'::jsonb,'https://press.ktm.com/news-ktms-no-bullshit-campaign-roars-to-life-with-the-brand-new-2024-single-cylinder-ktm-duke-line-up?id=184141&l=uk&menueid=5904'),
(926,7,'Documented model history','{"summary":"KTM''s 22 August 2023 UK announcement records a significant redesign for the 2024 125 Duke; the statement identifies the original 125 Duke launch as 2011.","source_name":"KTM official model history","source_url":"https://press.ktm.com/news-ktms-no-bullshit-campaign-roars-to-life-with-the-brand-new-2024-single-cylinder-ktm-duke-line-up?id=184141&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original model- and year-scoped evidence summary. Independent factual review and licensing required; do not publish automatically."}'::jsonb,'https://press.ktm.com/news-ktms-no-bullshit-campaign-roars-to-life-with-the-brand-new-2024-single-cylinder-ktm-duke-line-up?id=184141&l=uk&menueid=5904'),
(926,12,'2024-generation engineering','{"summary":"The 2024 Duke range introduced a revised two-piece chassis with steel trellis main frame and die-cast aluminium subframe; detailed model-specific equipment requires independent checking.","source_name":"KTM official model history","source_url":"https://press.ktm.com/news-ktms-no-bullshit-campaign-roars-to-life-with-the-brand-new-2024-single-cylinder-ktm-duke-line-up?id=184141&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original model- and year-scoped evidence summary. Independent factual review and licensing required; do not publish automatically."}'::jsonb,'https://press.ktm.com/news-ktms-no-bullshit-campaign-roars-to-life-with-the-brand-new-2024-single-cylinder-ktm-duke-line-up?id=184141&l=uk&menueid=5904'),
(225,1,'Model introduction','{"summary":"The Continental GT 535 revived Royal Enfield''s cafe-racer theme with a single-cylinder engine, and is a distinct motorcycle from the later GT 650 twin.","source_name":"Royal Enfield official model history","source_url":"https://devcdn.royalenfield.com/ae/en/our-world/since-1901/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original model- and year-scoped evidence summary. Independent factual review and licensing required; do not publish automatically."}'::jsonb,'https://devcdn.royalenfield.com/ae/en/our-world/since-1901/'),
(225,7,'Documented model history','{"summary":"Royal Enfield''s company history dates the introduction of the Continental GT with its 535 cc UCE engine to 2013.","source_name":"Royal Enfield official model history","source_url":"https://devcdn.royalenfield.com/ae/en/our-world/since-1901/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original model- and year-scoped evidence summary. Independent factual review and licensing required; do not publish automatically."}'::jsonb,'https://devcdn.royalenfield.com/ae/en/our-world/since-1901/'),
(225,12,'Original-generation engineering','{"summary":"Royal Enfield''s corporate history identifies a Harris Performance-designed cradle chassis for the 2013 Continental GT. Specifications for other markets and later production need separate evidence.","source_name":"Royal Enfield official model history","source_url":"https://devcdn.royalenfield.com/ae/en/our-world/since-1901/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original model- and year-scoped evidence summary. Independent factual review and licensing required; do not publish automatically."}'::jsonb,'https://devcdn.royalenfield.com/ae/en/our-world/since-1901/'),
(929,1,'Model introduction','{"summary":"Moto Guzzi''s modern V7 roadster family retains the transverse V-twin concept that has long been central to the company''s motorcycles.","source_name":"Moto Guzzi official model history","source_url":"https://www.motoguzzi.com/en_EN/moto-guzzi/en/new-moto-guzzi-v7/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original model- and year-scoped evidence summary. Independent factual review and licensing required; do not publish automatically."}'::jsonb,'https://www.motoguzzi.com/en_EN/moto-guzzi/en/new-moto-guzzi-v7/'),
(929,7,'Documented model generations','{"summary":"Moto Guzzi''s announcement for the newer 850 cc V7 generation distinguishes the V7 Stone and V7 Special; the article does not establish original historic V7 production chronology.","source_name":"Moto Guzzi official model history","source_url":"https://www.motoguzzi.com/en_EN/moto-guzzi/en/new-moto-guzzi-v7/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original model- and year-scoped evidence summary. Independent factual review and licensing required; do not publish automatically."}'::jsonb,'https://www.motoguzzi.com/en_EN/moto-guzzi/en/new-moto-guzzi-v7/'),
(929,12,'850-generation factory engineering','{"summary":"Moto Guzzi reports a new 850 cc engine producing 65 hp in the referenced generation with switchable traction control. The details must not be applied to older V7 versions.","source_name":"Moto Guzzi official model history","source_url":"https://www.motoguzzi.com/en_EN/moto-guzzi/en/new-moto-guzzi-v7/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Original model- and year-scoped evidence summary. Independent factual review and licensing required; do not publish automatically."}'::jsonb,'https://www.motoguzzi.com/en_EN/moto-guzzi/en/new-moto-guzzi-v7/')) AS v(model_id,slot,title,content,source_url);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>15 THEN RAISE EXCEPTION 'Expected 15 research drafts, inserted %',inserted; END IF;
 SELECT count(*) INTO new_pub FROM public.motorcycle_universal_published_sections_v1;
 IF old_pub<>new_pub THEN RAISE EXCEPTION 'Universal published sections changed'; END IF;
END $$;